                dc = 1 if c2 > c1 else -1
                length = abs(r2 - r1)
                segments.append((r1, c1, dr, dc, length))
                for k in range(length + 1):
                    r, c = r1 + k * dr, c1 + k * dc
                    if grid[r][c] != 6:
                        out[r][c] = 1

    # A 6 on a 1-connecting diagonal extends along the perpendicular diagonal.
    for r, c in sixes:
        for r1, c1, dr, dc, length in segments:
            k = (r - r1) * dr
            if 0 <= k <= length and (r, c) == (r1 + k * dr, c1 + k * dc):
                pdc = -dc
                for step in range(-max(h, w), max(h, w) + 1):
                    rr, cc = r + step, c + step * pdc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 6
                break

    return out
